final class tm extends ffi.Struct {
  @ffi.Int()
  external int tm_sec;

  @ffi.Int()
  external int tm_min;

  @ffi.Int()
  external int tm_hour;

  @ffi.Int()
  external int tm_mday;

  @ffi.Int()
  external int tm_mon;

  @ffi.Int()
  external int tm_year;

  @ffi.Int()
  external int tm_wday;

  @ffi.Int()
  external int tm_yday;

  @ffi.Int()
  external int tm_isdst;

  @ffi.Long()
  external int tm_gmtoff;

  external ffi.Pointer<ffi.Char> tm_zone;

  static ffi.Pointer<tm> $allocate(
    ffi.Allocator $allocator, {
    required int tm_sec,
    required int tm_min,
    required int tm_hour,
    required int tm_mday,
    required int tm_mon,
    required int tm_year,
    required int tm_wday,
    required int tm_yday,
    required int tm_isdst,
    required int tm_gmtoff,
    required ffi.Pointer<ffi.Char> tm_zone,
  }) => $allocator<tm>()
    ..ref.tm_sec = tm_sec
    ..ref.tm_min = tm_min
    ..ref.tm_hour = tm_hour
    ..ref.tm_mday = tm_mday
    ..ref.tm_mon = tm_mon
    ..ref.tm_year = tm_year
    ..ref.tm_wday = tm_wday
    ..ref.tm_yday = tm_yday
    ..ref.tm_isdst = tm_isdst
    ..ref.tm_gmtoff = tm_gmtoff
    ..ref.tm_zone = tm_zone;
}
